#include "../src/native_temporal_mode.h"
#include <cassert>
#include <iostream>
int main(){assert(NativeParseTemporalMode({},false)==NativeTemporalMode::Off);assert(NativeParseTemporalMode({},true)==NativeTemporalMode::FastHistory);for(bool old:{false,true}){assert(NativeParseTemporalMode(std::string("0"),old)==NativeTemporalMode::Off);assert(NativeParseTemporalMode(std::string("1"),old)==NativeTemporalMode::FastHistory);assert(NativeParseTemporalMode(std::string("2"),old)==NativeTemporalMode::LowFrequency);}assert(NativeParseTemporalMode(std::string("3"),true)==NativeTemporalMode::Enhance);assert(NativeParseTemporalEnhancementStrength({})==1.f);assert(NativeParseTemporalEnhancementStrength(std::string("0"))==0.f);assert(NativeParseTemporalEnhancementStrength(std::string("2"))==2.f);for(auto s:{"nan","inf","-1","2.1","","1x"}){bool fail=false;try{NativeParseTemporalEnhancementStrength(std::string(s));}catch(...){fail=true;}assert(fail);}for(auto s:{"","4","true"," 1"}){bool fail=false;try{NativeParseTemporalMode(std::string(s),true);}catch(...){fail=true;}assert(fail);}std::cout<<"PASS selector explicit presence/legacy mapping/invalid rejection\n";}
